summaryData.forEach((row, i) => {
  const r = summary.addRow(row);
  if (i === 0) { r.getCell(1).font = { bold: true, size: 16, color: { argb: 'FF1F4E79' } }; summary.mergeCells(1, 1, 1, 4); }
  if (i === 1 || i === 2) { r.getCell(1).font = { size: 11, italic: true, color: { argb: 'FF666666' } }; summary.mergeCells(i + 1, 1, i + 1, 4); }
  if (i === 4) { r.eachCell(cell => { cell.font = HEADER_FONT; cell.fill = HEADER_FILL; cell.border = BORDER; }); }
  if (i >= 5 && i <= 16) { r.eachCell(cell => { cell.border = BORDER; }); if (i % 2 === 1) r.eachCell(cell => { cell.fill = ALT_FILL; }); }
  if (i === 18) { r.getCell(1).font = { bold: true, size: 12, color: { argb: 'FF1F4E79' } }; r.getCell(3).font = { bold: true, size: 14, color: { argb: 'FF1F4E79' } }; r.eachCell(cell => { cell.border = BORDER; cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFDAEEF3' } }; }); }
  if (i === 20 || i === 31) { r.getCell(1).font = { bold: true, size: 11 }; }
  if (i > 20) { r.getCell(1).font = { ...(r.getCell(1).font || {}), size: 10, color: { argb: 'FF333333' } }; }
});

summary.getColumn(1).width = 52; summary.getColumn(2).width = 35; summary.getColumn(3).width = 16; summary.getColumn(4).width = 26;

